// Sniperモード自動最適化 2026-04-25 11:03 / 1199件データ
// Sniper: 17件 勝率76.5% 平均1.5%
// 【Sniper条件（全6条件通過で採択）】
//   ① close > EMA25（中期トレンド）
//   ② 強い陽線（実体≥0.5%）
//   ③ MACD hist > 0
//   ④ ATR% < 5.0%
//   ⑤ 直近20日高値更新
//   ⑥ RSI 40〜60

function calculateScoreSniper(ind) {
  if (!ind) return null;
  const filters = [];
  let score = 0;

  // ① close > EMA25（中期トレンド）
  if (ind.ema25 !== null && ind.close > ind.ema25) {
    score++;
    filters.push(`①EMA25順張り`);
  }

  // ② 強い陽線（実体≥0.5%）
  if (ind.isStrongBull) {
    score++;
    filters.push(`②強陽線(${ind.bodyPct.toFixed(1)}%)`);
  }

  // ③ MACD hist > 0
  if (ind.macdPos) {
    score++;
    filters.push(`③MACD上昇`);
  }

  // ④ ATR% < 5.0%
  if (ind.atrPct < 5.0) {
    score++;
    filters.push(`④ATR(${ind.atrPct}%)`);
  }

  // ⑤ 直近20日高値更新
  if (ind.hiBrk20) {
    score++;
    filters.push(`⑤高値更新`);
  }

  // ⑥ RSI 40〜60
  if (!isNaN(ind.rsi14) && ind.rsi14 >= 40 && ind.rsi14 < 60) {
    score++;
    filters.push(`⑥RSI(${ind.rsi14.toFixed(0)})`);
  }

  return { score, filters };
}
